/bin/bash -lc "python - <<'PY'
from PyQt5.QtCore import QUrl
u = QUrl('http://ex4mple.com:8080/a%3A5/%C3%B6?x=%3A10&v=7#%3A10')
for name in ('host','path','query','fragment'):
    get = getattr(u, name)
    for fmt_name in ('default','FullyEncoded','FullyDecoded'):
        fmt = None if fmt_name == 'default' else getattr(QUrl,fmt_name)
        try: print(name,fmt_name,get() if fmt is None else get(fmt))
        except Exception as e: print(name,fmt_name,type(e).__name__,str(e))
print('encoded',bytes(u.toEncoded()).decode())
for name, value in [('setPath','/a%3A6/%C3%B6'),('setQuery','x=%3A11&v=7'),('setFragment','%3A11'),('setHost','ex5mple.com')]:
    for mode in ('default','DecodedMode','StrictMode','TolerantMode'):
        v = QUrl(u)
        try:
            setter = getattr(v,name)
            if mode=='default': setter(value)
            else: setter(value,getattr(QUrl,mode))
            print(name,mode,bytes(v.toEncoded()).decode())
        except Exception as e: print(name,mode,type(e).__name__,str(e))
PY"

